def match_parens(lst):
    def is_well_formed(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    if len(lst) != 2:
        return 'No'

    open_count_1 = lst[0].count('(')
    close_count_1 = lst[0].count(')')
    open_count_2 = lst[1].count('(')
    close_count_2 = lst[1].count(')')

    if open_count_1 != close_count_1 or open_count_2 != close_count_2:
        return 'No'

    combined_string = lst[0] + lst[1]

    return 'Yes' if is_well_formed(combined_string) else 'No'

